def section(lang='de',base=''):
 import json
 c=COPY[lang]
 c['rate_labels']={'de':['je Anzeigenklick','Anfragequote','Abschlussquote'],'en':['per ad click','enquiry rate','closing rate'],'sq':['për klikim reklame','norma e kërkesave','norma e mbylljes']}[lang]
 specs=[('website',2500,100000),('social',500,20000),('seo',350,20000),('local',100,10000),('ads',500,50000)]
 cards=''.join(f'<div class="planner-service" data-planner-service="{key}"><label class="planner-service-choice"><input type="checkbox" data-plan-active="{key}" checked><span><strong>{e(c["services"][i])}</strong><small>{e(c["service_notes"][i])}</small></span></label><label class="planner-budget"><span class="planner-sr">{e(c["budget"])}: {e(c["services"][i])}</span><span><input type="number" min="0" max="{maximum}" step="50" value="{value}" data-plan-value="{key}" inputmode="decimal" aria-label="{e(c["budget"])}: {e(c["services"][i])}"> €</span><small>{c["once"] if key=="website" else c["monthly"]}</small></label></div>' for i,(key,value,maximum) in enumerate(specs))
 assumptions=[('baseVisitors',300,0,1000000,10),('socialViews',2500,0,10000000,100),('socialCtr',1,0,100,.1),('seoVisits',150,0,1000000,10),('localViews',500,0,1000000,10),('localCtr',10,0,100,1),('cpc',2,.1,100,.1),('adCtr',2,.1,100,.1),('baseCvr',2,0,100,.1),('targetCvr',3,0,100,.1),('closeRate',25,0,100,1)]
 fields=''.join(f'<label>{e(c["fields"][i])}<input type="number" min="{lo}" max="{hi}" step="{step}" value="{value}" data-plan-value="{key}" inputmode="decimal"></label>' for i,(key,value,lo,hi,step) in enumerate(assumptions))
 metrics=''.join(f'<div class="planner-metric"><span>{e(label)}</span><strong data-plan-output="{key}">–</strong></div>' for key,label in zip(['impressions','addedVisits','addedLeads','customers'],c['metrics']))
 config=json.dumps(dict(lang=lang,labels=c,recipient=RECIPIENT,endpoint=ENDPOINT),ensure_ascii=False).replace('<','\\u003c')
 return f'''<section class="budget-planner" id="budgetplaner" data-planner data-boosty-section="marketing"><div class="shell"><div class="planner-heading"><div><p class="v-kicker">{c['kicker']}</p><h2>{c['title']}</h2></div><p>{e(c['intro'])}</p></div><div class="planner-interface" data-planner-interface><div class="planner-layout"><div class="planner-inputs"><h3><span>01</span>{e(c['choose'])}</h3><p class="planner-example">{e(c['example'])}</p><div class="planner-services">{cards}</div><div class="planner-ad-slider"><label for="plan-ad-range">{e(c['adbudget'])}<output data-plan-ad-label>500 €</output></label><input id="plan-ad-range" type="range" min="0" max="5000" step="50" value="500" data-plan-ad-range><div><span>0 €</span><span>5.000 €</span></div></div><div class="planner-mobile-live"><span><small>{e(c['monthly_label'])}</small><b data-plan-output="monthly">–</b></span><span><small>{e(c['metrics'][3])}</small><b data-plan-output="customers">–</b></span><a href="#planner-ergebnis">{e(c['explain'])} ↓</a></div><details class="planner-assumptions"><summary>{e(c['assumptions'])}<span aria-hidden="true">+</span></summary><p>{e(c['assumption_note'])}</p><div>{fields}</div></details></div><div class="planner-results" id="planner-ergebnis"><p class="planner-result-kicker">{c['result']}</p><div class="planner-costs"><div><span>{e(c['once_label'])}</span><strong data-plan-output="once">–</strong></div><div><span>{e(c['monthly_label'])}</span><strong data-plan-output="monthly">–</strong></div></div><div class="planner-metrics" aria-live="off">{metrics}</div><p class="planner-key-assumptions" data-plan-assumption-line></p><p class="planner-model-note">{e(c['model_note'])}</p><div class="planner-chart"><h3>{e(c['chart'])}</h3><svg viewBox="0 0 480 150" role="img" aria-labelledby="planner-chart-title"><title id="planner-chart-title">{e(c['chart'])}</title><path class="planner-chart-grid" d="M36 18H465M36 65H465M36 112H465"/><path class="planner-chart-area" data-plan-chart-area d=""/><path class="planner-chart-line" data-plan-chart-line d=""/><circle data-plan-chart-dot r="5" cx="36" cy="112"/><g data-plan-chart-axis></g></svg><div class="planner-chart-ticks" data-plan-chart-ticks></div><p>{e(c['chart_note'])}</p></div><details class="planner-math"><summary>{e(c['explain'])}</summary><p>{e(c['formula'])}</p><p>{e(c['organic'])}</p></details></div></div><div class="planner-bottom"><a href="{base}leistungen.html">{e(c['more'])} ↗</a><button type="button" data-plan-download>{e(c['download'])} ↓</button></div><details class="planner-inquiry" data-plan-inquiry><summary>{e(c['request'])}<span aria-hidden="true">↗</span></summary><div class="planner-inquiry-body"><div><p class="v-kicker">TAFOLLI &amp; CO.</p><h3>{e(c['request'])}</h3><p>{e(c['form_intro'])}</p><div class="planner-send-summary" data-plan-send-summary></div></div><form data-plan-form action="{ACTION}" method="post"><div class="planner-form-grid"><label>{e(c['name'])}<input name="name" autocomplete="name" required maxlength="120"></label><label>{e(c['company'])}<input name="company" autocomplete="organization" maxlength="160"></label><label>{e(c['email'])}<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label>{e(c['phone'])}<input name="phone" type="tel" autocomplete="tel" maxlength="60"></label></div><label>{e(c['message'])}<textarea name="message" rows="3" maxlength="1500"></textarea></label><label class="planner-honey" aria-hidden="true">Website<input name="_honey" tabindex="-1" autocomplete="off"></label><input type="hidden" name="_subject" value="{e(c['subject'])}"><input type="hidden" name="_template" value="table"><input type="hidden" name="_url" value="https://tafolli.net/"><textarea name="Planung" data-plan-mail-summary hidden></textarea><p class="planner-form-privacy">{e(c['privacy'])} <a href="{base}datenschutz.html#budgetplaner-datenschutz">{e(c['privacy_link'])}</a>.</p><button class="btn btn-1" type="submit">{e(c['submit'])} ↗</button><p class="planner-form-status" data-plan-status role="status"></p><a class="planner-mail-fallback" data-plan-mailto href="mailto:info@tafolli.net">{e(c['fallback'])} ↗</a></form></div></details></div><noscript><style>.planner-interface{{display:none}}</style><p class="planner-noscript">{e(c['noscript'])} <a href="{base}kontakt.html">{e(c['submit'])} ↗</a></p></noscript></div><script type="application/json" data-planner-config>{config}</script></section>'''
